if __name__ == "__main__":
    revise_domain("252", "252_traditional_sports", TRADITIONAL_SPORTS,
                  "Community sports through rules, venues, teaching, participation, formalization, and access.",
                  "dated rulebooks and event records, venue documents, participation data, equipment provenance, and consented player and organizer accounts",
                  "Name sport, community, rule set, place, and date. Verify current organizer rules and site conditions; do not substitute this research plan for safety or medical guidance.")
